import { Route, Routes } from 'react-router-dom';
import { PublicShell } from './components/PublicShell';
import {
  CompetitionDetailPage,
  CompetitionsPage,
  CompetitorDetailPage,
  CompetitorsPage,
  FixtureDetailPage,
  FixturesPage,
  NotFoundPage,
  ParticipantDetailPage,
  ParticipantsPage,
  SeasonDetailPage,
  SeasonsPage,
} from './pages/PublicBrowsePages';
import { useEffect } from 'react';
import {
  AccountPage,
  AuthenticationCallbackPage,
  AuthenticationPage,
} from './features/auth/AuthPages';
import { SubmissionPage } from './features/submissions/SubmissionPage';
import {
  FixtureStatisticDetailPage,
  FixtureStatisticsPage,
} from './features/statistics/StatisticsPages';
import { AdminUsersPage } from './features/admin/AdminUsersPage';

function HeroLogo() {
  return (
    <div className="hero__brand-art" aria-hidden="true">
      <img
        className="hero__logo brand-asset--day"
        src="/brand/statsthegame-mark-light.svg"
        alt=""
      />
      <img
        className="hero__logo brand-asset--night"
        src="/brand/statsthegame-mark-dark.svg"
        alt=""
      />
    </div>
  );
}

function LandingPage() {
  useEffect(() => {
    document.title = "Stat'sTheGame";
  }, []);

  return (
    <>
      <section className="hero" aria-labelledby="page-title">
        <HeroLogo />
        <div className="hero__content">
          <p className="eyebrow">Public T20 cricket record</p>
          <h1 id="page-title">Stat&rsquo;sTheGame</h1>
          <p className="hero__tagline">The game, measured ball by ball.</p>
          <p className="hero__summary">
            An event-driven home for published cricket records, designed to keep every result
            connected to the deliveries behind it.
          </p>
        </div>
      </section>

      <section className="principles" aria-labelledby="principles-title">
        <div className="content-boundary">
          <div className="section-heading">
            <p className="eyebrow">Our standard</p>
            <h2 id="principles-title">Explosive. Exact. Traceable.</h2>
          </div>

          <div className="principles__grid">
            <article>
              <p className="principle-number" aria-hidden="true">
                01
              </p>
              <h3>Event-led</h3>
              <p>Published figures begin with accepted, event-level cricket data.</p>
            </article>
            <article>
              <p className="principle-number" aria-hidden="true">
                02
              </p>
              <h3>Public by design</h3>
              <p>Published cricket records are available without an account.</p>
            </article>
            <article>
              <p className="principle-number" aria-hidden="true">
                03
              </p>
              <h3>Built for evidence</h3>
              <p>Every published result is designed to remain connected to its source.</p>
            </article>
          </div>
        </div>
      </section>
    </>
  );
}

export function PublicApp() {
  return (
    <PublicShell>
      <Routes>
        <Route path="/" element={<LandingPage />} />

        <Route path="/competitions" element={<CompetitionsPage />} />
        <Route path="/competitions/:competitionId" element={<CompetitionDetailPage />} />

        <Route path="/seasons" element={<SeasonsPage />} />
        <Route path="/seasons/:seasonId" element={<SeasonDetailPage />} />

        <Route path="/fixtures" element={<FixturesPage />} />
        <Route path="/fixtures/:fixtureId" element={<FixtureDetailPage />} />
        <Route path="/fixtures/:fixtureId/statistics" element={<FixtureStatisticsPage />} />
        <Route
          path="/fixtures/:fixtureId/statistics/:statisticId"
          element={<FixtureStatisticDetailPage />}
        />

        <Route path="/competitors" element={<CompetitorsPage />} />
        <Route path="/competitors/:competitorId" element={<CompetitorDetailPage />} />

        <Route path="/participants" element={<ParticipantsPage />} />
        <Route path="/participants/:participantId" element={<ParticipantDetailPage />} />

        <Route path="/sign-in" element={<AuthenticationPage />} />
        <Route path="/auth/callback" element={<AuthenticationCallbackPage />} />
        <Route path="/account" element={<AccountPage />} />
        <Route path="/submissions/new" element={<SubmissionPage />} />
        <Route path="/admin/users" element={<AdminUsersPage />} />

        <Route path="*" element={<NotFoundPage />} />
      </Routes>
    </PublicShell>
  );
}

function App() {
  return <PublicApp />;
}

export default App;

:root,
:root[data-theme='day'] {
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --radius-control: 6px;
  --radius-card: 10px;
  --ease-fast: cubic-bezier(0.2, 0.8, 0.2, 1);
  --colour-canvas: #f5f2e9;
  --colour-surface: #fffdf7;
  --colour-surface-raised: #eee9dc;
  --colour-text: #102026;
  --colour-text-secondary: #52636a;
  --colour-text-muted: #627078;
  --colour-border: #d9d3c4;
  --colour-primary: #5d7e00;
  --colour-primary-soft: #dff0a7;
  --colour-brand: #e95a24;
  --colour-data-accent: #007f9e;
  --colour-link: #005f77;
  --colour-label: #486200;
  --colour-brand-text: #a83b13;
  --colour-error: #b42318;
  --colour-focus: #007f9e;
  --colour-error: #d64251;
  --colour-error-soft: #fce8e8;
  --shadow-header: 0 8px 28px rgb(16 32 38 / 8%);
  --font-display: 'Arial Narrow', 'Roboto Condensed', Arial, sans-serif;
  --font-interface: 'Segoe UI', Arial, sans-serif;
  color: var(--colour-text);
  background: var(--colour-canvas);
  font-family: var(--font-interface);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}

/* Reusable component baseline. Consume these semantic tokens in new UI work. */
.ui-page-layout {
  padding-block: var(--space-8) var(--space-16);
}

.ui-page-layout__header {
  max-width: 48rem;
  margin-bottom: var(--space-8);
  padding-bottom: var(--space-5);
  border-bottom: 2px solid var(--colour-primary);
}

.ui-page-layout__header h1 {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 5vw, 3rem);
  line-height: 1.08;
}

.ui-page-layout__header p {
  margin: var(--space-3) 0 0;
  color: var(--colour-text-secondary);
  line-height: 1.5;
}

.ui-button {
  min-height: 2.75rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.625rem 1rem;
  border: 1px solid transparent;
  border-radius: var(--radius-control);
  font: inherit;
  font-weight: 600;
  line-height: 1.25;
  cursor: pointer;
  transition:
    background-color 120ms var(--ease-fast),
    border-color 120ms var(--ease-fast),
    color 120ms var(--ease-fast);
}

.ui-button--primary {
  background: var(--colour-primary);
  color: #fff;
}
:root[data-theme='night'] .ui-button--primary {
  color: var(--colour-canvas);
}
.ui-button--secondary {
  border-color: var(--colour-border);
  background: var(--colour-surface);
  color: var(--colour-text);
}
.ui-button--destructive {
  background: var(--colour-error);
  color: #fff;
}
.ui-button:hover:not(:disabled) {
  filter: brightness(0.94);
}
.ui-button:disabled {
  cursor: not-allowed;
  opacity: 0.65;
}

.ui-field {
  display: grid;
  gap: var(--space-2);
  max-width: 47.5rem;
}
.ui-field > label {
  color: var(--colour-text);
  font-size: 0.875rem;
  font-weight: 600;
}
.ui-field__input {
  width: 100%;
  min-width: 0;
  min-height: 2.75rem;
  padding: 0.625rem 0.75rem;
  border: 1px solid var(--colour-border);
  border-radius: var(--radius-control);
  background: var(--colour-surface);
  color: var(--colour-text);
}
.ui-field__input[aria-invalid='true'] {
  border-color: var(--colour-error);
  box-shadow: 0 0 0 1px var(--colour-error);
}
.ui-field__help,
.ui-field__error {
  margin: 0;
  font-size: 0.875rem;
  line-height: 1.45;
}
.ui-field__help {
  color: var(--colour-text-secondary);
}
.ui-field__error {
  color: var(--colour-error);
  font-weight: 600;
}

.ui-card {
  padding: var(--space-6);
  border: 1px solid var(--colour-border);
  border-radius: var(--radius-card);
  background: var(--colour-surface);
}
.ui-card__heading {
  margin: 0 0 var(--space-4);
  font-family: var(--font-display);
  font-size: 1.375rem;
  line-height: 1.2;
}

.ui-message {
  margin-block: var(--space-4);
  padding: var(--space-4);
  border-inline-start: 3px solid var(--colour-data-accent);
  background: var(--colour-surface-raised);
  color: var(--colour-text);
}
.ui-message--success {
  border-inline-start-color: var(--colour-success);
}
.ui-message--warning {
  border-inline-start-color: var(--colour-warning);
}
.ui-message--error {
  border-inline-start-color: var(--colour-error);
  background: var(--colour-error-soft);
}
.ui-message__heading {
  margin: 0 0 var(--space-2);
  font-size: 1rem;
}
.ui-message p {
  margin: 0;
  line-height: 1.5;
}

.ui-data-table {
  max-width: 100%;
  overflow-x: auto;
  border: 1px solid var(--colour-border);
  border-radius: var(--radius-card);
}
.ui-data-table:focus-visible {
  outline: 3px solid var(--colour-focus);
  outline-offset: 3px;
}
.ui-data-table__table {
  width: 100%;
  min-width: 34rem;
  border-collapse: collapse;
  background: var(--colour-surface);
}
.ui-data-table__table caption {
  padding: var(--space-3) var(--space-4);
  color: var(--colour-text-secondary);
  font-size: 0.875rem;
  text-align: left;
}
.ui-data-table__table th,
.ui-data-table__table td {
  padding: var(--space-3) var(--space-4);
  border-top: 1px solid var(--colour-border);
  text-align: left;
}
.ui-data-table__table th {
  background: var(--colour-surface-raised);
  font-size: 0.8125rem;
}
.ui-data-table__table [data-numeric] {
  font-variant-numeric: tabular-nums;
  text-align: right;
}

@media (max-width: 39.9375rem) {
  .ui-page-layout {
    padding-block: var(--space-6) var(--space-12);
  }
  .ui-card {
    padding: var(--space-4);
  }
  .ui-button {
    width: 100%;
  }
}

:root[data-theme='night'] {
  --colour-canvas: #08121b;
  --colour-surface: #101e2b;
  --colour-surface-raised: #162736;
  --colour-text: #f6f8f2;
  --colour-text-secondary: #b8c3cc;
  --colour-text-muted: #8ea0af;
  --colour-border: #263847;
  --colour-primary: #c7ff4a;
  --colour-primary-soft: #263b21;
  --colour-brand: #ff6b35;
  --colour-data-accent: #20d5ff;
  --colour-link: #20d5ff;
  --colour-label: #c7ff4a;
  --colour-brand-text: #ff8a5e;
  --colour-error: #ff8a7a;
  --colour-focus: #c7ff4a;
  --colour-error: #ff5a67;
  --colour-error-soft: #361b24;
  --shadow-header: 0 8px 28px rgb(0 0 0 / 24%);
}

* {
  box-sizing: border-box;
}

html {
  min-width: 320px;
  background: var(--colour-canvas);
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  overflow-x: hidden;
  background: var(--colour-canvas);
  color: var(--colour-text);
}

button,
input,
select {
  font: inherit;
}

a {
  color: var(--colour-link);
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible {
  outline: 3px solid var(--colour-focus);
  outline-offset: 4px;
}

.public-shell {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.skip-link {
  position: fixed;
  left: 1rem;
  top: -5rem;
  z-index: 100;
  padding: 0.75rem 1rem;
  border: 2px solid var(--colour-focus);
  border-radius: 6px;
  background: var(--colour-surface);
  color: var(--colour-text);
  font-weight: 600;
  text-decoration: none;
}

.skip-link:focus {
  top: 1rem;
}

.site-header {
  position: relative;
  z-index: 10;
  border-bottom: 1px solid var(--colour-border);
  background: var(--colour-surface);
  box-shadow: var(--shadow-header);
}

.site-header__inner,
.site-footer__inner,
.content-boundary {
  width: min(100% - 3rem, 100rem);
  margin-inline: auto;
}

.site-header__inner {
  min-height: 5.5rem;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 1.5rem;
}

.site-header__controls,
.auth-navigation,
.auth-navigation-wrap {
  display: flex;
  align-items: center;
}

.site-header__controls {
  justify-content: flex-end;
  gap: 1.5rem;
}

.auth-navigation-wrap {
  position: relative;
  align-self: stretch;
}

.auth-navigation {
  gap: 0.5rem;
}

.auth-navigation a,
.auth-navigation button {
  min-height: 2.75rem;
  display: inline-flex;
  align-items: center;
  padding: 0.625rem 0.75rem;
  border: 1px solid transparent;
  border-radius: 6px;
  background: transparent;
  color: var(--colour-text);
  font-weight: 600;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
}

.auth-navigation a:hover,
.auth-navigation button:hover:not(:disabled),
.auth-navigation a[aria-current='page'] {
  border-color: var(--colour-border);
  background: var(--colour-surface-raised);
}

.auth-navigation a[aria-current='page'] {
  box-shadow: inset 0 -3px var(--colour-primary);
}

.auth-navigation button:disabled {
  cursor: wait;
  opacity: 0.7;
}

.auth-navigation__status {
  margin: 0;
  color: var(--colour-text-secondary);
  font-size: 0.875rem;
}

.auth-navigation__error {
  position: absolute;
  top: calc(100% - 0.25rem);
  right: 0;
  width: max-content;
  max-width: min(22rem, calc(100vw - 2rem));
  margin: 0;
  padding: 0.75rem 1rem;
  border: 1px solid var(--colour-error);
  border-radius: 6px;
  background: var(--colour-surface);
  color: var(--colour-error);
  box-shadow: var(--shadow-header);
  font-size: 0.875rem;
}

.brand-link {
  display: inline-flex;
  align-items: center;
  min-width: 0;
  border-radius: 6px;
}

.brand-wordmark {
  display: block;
  width: 11rem;
  max-width: 100%;
}

.brand-wordmark__image {
  display: block;
  width: 100%;
  height: auto;
}

.site-navigation {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.25rem;
}

.site-navigation a {
  position: relative;
  padding: 0.75rem 0.625rem;
  border-radius: 6px;
  color: var(--colour-text-secondary);
  font-size: 0.8125rem;
  font-weight: 650;
  text-align: center;
  text-decoration: none;
}

.site-navigation a:hover {
  background: var(--colour-surface-raised);
  color: var(--colour-text);
}

.site-navigation a.active {
  background: var(--colour-primary-soft);
  color: var(--colour-text);
}

.site-navigation a.active::after {
  content: '';
  position: absolute;
  right: 0.625rem;
  bottom: 0.375rem;
  left: 0.625rem;
  border-bottom: 2px solid var(--colour-primary);
}

.brand-asset--night {
  display: none;
}

:root[data-theme='night'] .brand-asset--day {
  display: none;
}

:root[data-theme='night'] .brand-asset--night {
  display: block;
}

.theme-control {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--colour-text-secondary);
}

.theme-control__label {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
}

.theme-toggle {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.625rem;
  cursor: pointer;
}

.theme-toggle input {
  position: absolute;
  width: 2.75rem;
  height: 1.5rem;
  margin: 0;
  opacity: 0;
  cursor: pointer;
}

.theme-toggle__track {
  width: 2.75rem;
  height: 1.5rem;
  flex: 0 0 auto;
  padding: 0.1875rem;
  border: 1px solid var(--colour-border);
  border-radius: 999px;
  background: var(--colour-surface-raised);
}

.theme-toggle__thumb {
  display: block;
  width: 1rem;
  height: 1rem;
  border-radius: 50%;
  background: var(--colour-primary);
  transform: translateX(0);
  transition: transform 160ms ease;
}

.theme-toggle input:checked + .theme-toggle__track .theme-toggle__thumb {
  transform: translateX(1.25rem);
}

.theme-toggle input:focus-visible + .theme-toggle__track {
  outline: 3px solid var(--colour-focus);
  outline-offset: 4px;
}

.theme-control__value {
  min-width: 5.75rem;
  color: var(--colour-text);
  font-size: 0.875rem;
  font-weight: 600;
}

main {
  flex: 1;
}

.auth-page {
  min-height: min(42rem, calc(100svh - 13.5rem));
  display: grid;
  place-items: center;
  padding-block: 4rem;
}

.auth-card {
  width: min(100%, 47.5rem);
  padding: 3rem;
  border: 1px solid var(--colour-border);
  border-radius: 10px;
  background: var(--colour-surface);
  box-shadow: var(--shadow-header);
}

.auth-card h1 {
  font-size: clamp(2.5rem, 8vw, 3.5rem);
  white-space: normal;
}

.auth-card__introduction,
.auth-card > p:not(.eyebrow, .auth-error) {
  max-width: 38rem;
  color: var(--colour-text-secondary);
  line-height: 1.6;
}

.auth-card__introduction {
  margin: 1.25rem 0 2rem;
  font-size: 1.0625rem;
}

.button {
  min-height: 3rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.25rem;
  border: 1px solid transparent;
  border-radius: 6px;
  font-weight: 600;
  cursor: pointer;
}

.button--primary {
  background: var(--colour-primary);
  color: #fff;
}

:root[data-theme='night'] .button--primary {
  color: #08121b;
}

.button:disabled {
  cursor: wait;
  opacity: 0.72;
}

.auth-error {
  margin: 1rem 0 0;
  color: var(--colour-error);
  font-weight: 600;
}

.auth-card__alternative {
  margin: 2rem 0 0;
}

.identity-details {
  margin: 2rem 0 0;
}

.identity-details div {
  padding-block: 1rem;
  border-block: 1px solid var(--colour-border);
}

.identity-details dt {
  color: var(--colour-text-secondary);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
}

.identity-details dd {
  margin: 0.5rem 0 0;
  font-weight: 600;
  overflow-wrap: anywhere;
}

.account-deletion {
  margin-top: 3rem;
  padding: 1.5rem;
  border: 1px solid var(--colour-error);
  border-radius: 6px;
  background: var(--colour-error-soft);
}

.account-deletion h2 {
  max-width: none;
  font-size: 1.75rem;
}

.account-deletion > p:not(.eyebrow, .auth-error) {
  max-width: 40rem;
  margin: 1rem 0 0;
  color: var(--colour-text-secondary);
  line-height: 1.6;
}

.account-deletion__form {
  display: grid;
  gap: 1.25rem;
  margin-top: 1.5rem;
}

.account-deletion__acknowledgement {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  line-height: 1.5;
}

.account-deletion__acknowledgement input {
  width: 1.25rem;
  height: 1.25rem;
  flex: 0 0 auto;
  margin-top: 0.125rem;
}

.account-deletion__confirmation {
  display: grid;
  gap: 0.5rem;
  font-weight: 600;
}

.account-deletion__confirmation input {
  width: min(100%, 20rem);
  min-height: 2.75rem;
  padding: 0.625rem 0.75rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface);
  color: var(--colour-text);
  font: inherit;
}

.account-deletion input:focus-visible,
.button--danger:focus-visible {
  outline: 3px solid var(--colour-focus);
  outline-offset: 3px;
}

.button--danger {
  justify-self: start;
  border-color: var(--colour-error);
  background: var(--colour-error);
  color: #fff;
}

.account-deletion__status {
  margin: 1rem 0 0;
  font-weight: 600;
}

.submitter-access-panel {
  margin-top: 2rem;
  padding-top: 2rem;
  border-top: 1px solid var(--colour-border);
}

.submitter-access-panel__heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.submitter-access-panel__heading .eyebrow {
  margin-bottom: 0.5rem;
}

.submitter-access-panel h2 {
  max-width: none;
  font-size: 1.75rem;
}

.submitter-access-state {
  flex: 0 0 auto;
  margin: 0;
  padding: 0.375rem 0.625rem;
  border: 1px solid var(--colour-border);
  border-radius: 999px;
  background: var(--colour-surface-raised);
  color: var(--colour-text-secondary);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.submitter-access-state--pending {
  border-color: var(--colour-brand);
  color: var(--colour-brand-text);
}

.submitter-access-state--approved {
  border-color: var(--colour-data-accent);
  color: var(--colour-text);
}

.submitter-access-state--rejected {
  border-color: var(--colour-error);
  color: var(--colour-error);
}

.submitter-access-panel__message,
.submitter-access-panel__error,
.submitter-access-feedback {
  margin: 1rem 0 0;
}

.submitter-access-panel__message,
.submitter-access-panel__error p,
.submitter-access-feedback {
  color: var(--colour-text-secondary);
  line-height: 1.6;
}

.submitter-access-panel__message > p,
.submitter-access-panel__error p {
  margin: 0;
}

.submitter-access-panel__message .button,
.submitter-access-panel__error .button {
  margin-top: 1rem;
}

.submitter-access-request {
  display: grid;
  gap: 0.5rem;
  width: min(100%, 32rem);
  margin-top: 1rem;
}

.submitter-access-request label {
  color: var(--colour-text);
  font-weight: 700;
}

.submitter-access-request select {
  width: 100%;
  min-height: 3rem;
  padding: 0.625rem 0.75rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface);
  color: var(--colour-text);
}

.submitter-access-request .field-help,
.submitter-access-panel__empty {
  margin: 0;
}

.submitter-access-panel__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.submitter-access-feedback {
  padding: 0.875rem 1rem;
  border-left: 3px solid var(--colour-data-accent);
  background: var(--colour-surface-raised);
}

.submitter-access-feedback--error {
  border-left-color: var(--colour-error);
  background: var(--colour-error-soft);
  color: var(--colour-error);
  font-weight: 600;
}

.submission-page {
  min-height: 38rem;
  padding-bottom: 5rem;
}

.admin-users-page {
  min-height: 38rem;
  padding-bottom: 5rem;
}

.admin-users-page__heading {
  border-bottom: 2px solid var(--colour-primary);
}

.admin-user-toolbar {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 1.5rem;
  padding-block: 2rem 1.25rem;
}

.admin-user-toolbar > div {
  display: grid;
  gap: 0.5rem;
  width: min(100%, 32rem);
}

.admin-user-toolbar label,
.admin-access-form legend {
  font-weight: 700;
}

.admin-user-toolbar input {
  width: 100%;
  min-height: 3rem;
  padding: 0.625rem 0.75rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface);
  color: var(--colour-text);
}

.admin-user-toolbar p {
  margin: 0 0 0.75rem;
  color: var(--colour-text-secondary);
  white-space: nowrap;
}

.admin-user-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.25rem;
}

.admin-user-card {
  min-width: 0;
  padding: 1.5rem;
  border: 1px solid var(--colour-border);
  border-radius: 10px;
  background: var(--colour-surface);
  box-shadow: var(--shadow-header);
}

.admin-user-card__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.admin-user-card__header h2 {
  margin: 0.25rem 0 0;
  font-size: 1.5rem;
  overflow-wrap: anywhere;
}

.admin-user-card__id {
  margin: 0;
  color: var(--colour-text-muted);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.admin-role-badge {
  flex: 0 0 auto;
  padding: 0.375rem 0.625rem;
  border: 1px solid var(--colour-border);
  border-radius: 999px;
  background: var(--colour-surface-raised);
  color: var(--colour-text-secondary);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.admin-role-badge--submitter {
  border-color: var(--colour-data-accent);
  color: var(--colour-text);
}

.admin-role-badge--admin {
  border-color: var(--colour-brand);
  color: var(--colour-brand-text);
}

.admin-user-facts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
  margin: 1.5rem 0;
}

.admin-user-facts div {
  min-width: 0;
}

.admin-user-facts__audit {
  grid-column: 1 / -1;
}

.admin-user-facts dt {
  color: var(--colour-text-muted);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.admin-user-facts dd {
  margin: 0.35rem 0 0;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.admin-access-form {
  padding-top: 1.25rem;
  border-top: 1px solid var(--colour-border);
}

.admin-user-card__request-state {
  margin: 0 0 1rem;
  padding: 1rem;
  border-left: 3px solid var(--colour-primary);
  background: var(--colour-primary-soft);
  color: var(--colour-text-secondary);
  line-height: 1.55;
}

.admin-user-card__request-state strong {
  color: var(--colour-text);
}

.admin-access-form fieldset {
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
}

.admin-access-form .field-help {
  margin-block: 0.5rem 0.75rem;
}

.admin-scope-options {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.5rem;
  max-height: 12rem;
  padding: 0.25rem;
  overflow-y: auto;
}

.admin-scope-options label {
  display: flex;
  align-items: flex-start;
  gap: 0.625rem;
  min-width: 0;
  padding: 0.625rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface-raised);
  cursor: pointer;
}

.admin-scope-options input {
  flex: 0 0 auto;
  width: 1.125rem;
  height: 1.125rem;
  margin: 0.1rem 0 0;
}

.admin-scope-options span {
  min-width: 0;
  overflow-wrap: anywhere;
}

.admin-access-form__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 1rem;
}

.button--danger {
  border-color: var(--colour-error);
  background: transparent;
  color: var(--colour-error);
}

.admin-access-form__error,
.admin-access-form__empty,
.admin-access-form__progress,
.admin-access-form__requested-scope,
.admin-user-card__protected,
.admin-access-feedback {
  margin: 1rem 0 0;
  line-height: 1.55;
}

.admin-access-form__error,
.admin-access-feedback--error {
  color: var(--colour-error);
  font-weight: 600;
}

.admin-user-card__protected {
  padding: 1rem;
  border-left: 3px solid var(--colour-border);
  background: var(--colour-surface-raised);
  color: var(--colour-text-secondary);
}

.admin-access-feedback {
  padding: 0.875rem 1rem;
  border-left: 3px solid var(--colour-data-accent);
  background: var(--colour-surface-raised);
}

.admin-access-feedback--error {
  border-left-color: var(--colour-error);
  background: var(--colour-error-soft);
}

.submission-page__heading {
  border-bottom: 2px solid var(--colour-primary);
}

.submission-form {
  display: grid;
  gap: 2rem;
  max-width: 62rem;
  padding-top: 2rem;
}

.submission-field {
  display: grid;
  gap: 0.625rem;
}

.submission-mode,
.submission-scope {
  display: grid;
  gap: 0.75rem;
  margin: 0;
  padding: 1rem 1.25rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface-raised);
}

.submission-mode legend,
.submission-scope h2 {
  padding: 0;
  margin: 0;
  font-family: var(--font-display);
  font-size: 1.125rem;
  font-weight: 700;
}

.submission-mode label {
  display: flex;
  gap: 0.625rem;
  align-items: center;
  width: fit-content;
}

.submission-scope p {
  margin: 0;
  color: var(--colour-text-secondary);
  line-height: 1.5;
}

.submission-field input[type='file'] {
  max-width: 100%;
  padding: 0.625rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface);
  color: var(--colour-text);
}

.submission-field label {
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 700;
}

