}

.admin-access-form__error,
.admin-access-feedback--error {
  color: var(--colour-error);
  font-weight: 600;
}

.admin-user-card__protected {
  padding: 1rem;
  border-left: 3px solid var(--colour-border);
  background: var(--colour-surface-raised);
  color: var(--colour-text-secondary);
}

.admin-access-feedback {
  padding: 0.875rem 1rem;
  border-left: 3px solid var(--colour-data-accent);
  background: var(--colour-surface-raised);
}

.admin-access-feedback--error {
  border-left-color: var(--colour-error);
  background: var(--colour-error-soft);
}

.submission-page__heading {
  border-bottom: 2px solid var(--colour-primary);
}

.submission-form {
  display: grid;
  gap: 2rem;
  max-width: 62rem;
  padding-top: 2rem;
}

.submission-field {
  display: grid;
  gap: 0.625rem;
}

.submission-mode,
.submission-scope {
  display: grid;
  gap: 0.75rem;
  margin: 0;
  padding: 1rem 1.25rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface-raised);
}

.submission-mode legend,
.submission-scope h2 {
  padding: 0;
  margin: 0;
  font-family: var(--font-display);
  font-size: 1.125rem;
  font-weight: 700;
}

.submission-mode label {
  display: flex;
  gap: 0.625rem;
  align-items: center;
  width: fit-content;
}

.submission-scope p {
  margin: 0;
  color: var(--colour-text-secondary);
  line-height: 1.5;
}

.submission-field input[type='file'] {
  max-width: 100%;
  padding: 0.625rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface);
  color: var(--colour-text);
}

.submission-field label {
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 700;
}

.submission-field select,
.submission-field textarea {
  width: 100%;
  min-width: 0;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface);
  color: var(--colour-text);
}

.submission-field select {
  min-height: 3rem;
  padding: 0.625rem 0.75rem;
}

.submission-field textarea {
  min-height: 24rem;
  padding: 1rem;
  resize: vertical;
  font-family: Consolas, 'Courier New', monospace;
  font-size: 0.875rem;
  line-height: 1.55;
  tab-size: 2;
  white-space: pre;
  overflow: auto;
}

.submission-field textarea[aria-invalid='true'] {
  border-color: var(--colour-error);
  box-shadow: 0 0 0 1px var(--colour-error);
}

.field-help,
.submission-progress {
  margin: 0;
  color: var(--colour-text-secondary);
  line-height: 1.5;
}

.field-help code {
  padding: 0.1rem 0.3rem;
  border-radius: 3px;
  background: var(--colour-surface-raised);
  color: var(--colour-text);
}

.submission-form > .button {
  justify-self: start;
}

.submission-result {
  padding: 1.5rem;
  border-left: 4px solid var(--colour-primary);
  background: var(--colour-primary-soft);
}

.submission-result--error {
  border-left-color: var(--colour-error);
  background: var(--colour-error-soft);
}

.submission-result h2 {
  max-width: none;
  font-size: 1.5rem;
}

.submission-result h2:focus {
  outline: 3px solid var(--colour-focus);
  outline-offset: 4px;
}

.submission-result > p {
  margin: 0.75rem 0 0;
  color: var(--colour-text-secondary);
  line-height: 1.55;
}

.submission-reference {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
  margin: 1.5rem 0 0;
}

.submission-reference div {
  min-width: 0;
}

.submission-reference dt {
  color: var(--colour-text-secondary);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.submission-reference dd {
  margin: 0.375rem 0 0;
  font-weight: 700;
  overflow-wrap: anywhere;
}

.validation-results {
  display: grid;
  gap: 0.75rem;
  margin: 1.5rem 0 0;
  padding-left: 1.5rem;
}

.validation-results li {
  padding-left: 0.25rem;
}

.validation-results strong,
.validation-results span {
  display: block;
}

.validation-results span {
  margin-top: 0.25rem;
  color: var(--colour-text-secondary);
  line-height: 1.5;
}

.correction-workspace {
  max-width: 62rem;
  margin-top: 3rem;
  padding-top: 2rem;
  border-top: 1px solid var(--colour-border);
}

.correction-workspace__intro {
  max-width: 48rem;
  margin: 1rem 0 0;
  color: var(--colour-text-secondary);
  line-height: 1.6;
}

.correction-event-picker {
  max-width: 32rem;
  margin-top: 2rem;
}

.correction-form {
  display: grid;
  gap: 1.5rem;
  margin-top: 2rem;
  padding: 1.5rem;
  border: 1px solid var(--colour-border);
  border-radius: var(--radius-md);
  background: var(--colour-surface-soft);
}

.correction-form__heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1.5rem;
}

.correction-form__heading h3,
.correction-form__heading p {
  margin: 0;
}

.correction-form__heading > p {
  color: var(--colour-text-secondary);
  text-align: right;
}

.correction-event-reference,
.correction-derived-values {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
  margin: 0;
}

.correction-event-reference div,
.correction-derived-values div {
  min-width: 0;
  padding: 1rem;
  border: 1px solid var(--colour-border);
  border-radius: var(--radius-sm);
  background: var(--colour-surface);
}

.correction-event-reference dt,
.correction-derived-values dt {
  color: var(--colour-text-secondary);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.correction-event-reference dd,
.correction-derived-values dd {
  margin: 0.375rem 0 0;
  font-weight: 700;
  overflow-wrap: anywhere;
}

.correction-fieldset {
  min-width: 0;
  margin: 0;
  padding: 1.25rem;
  border: 1px solid var(--colour-border);
  border-radius: var(--radius-sm);
  background: var(--colour-surface);
}

.correction-fieldset legend {
  padding: 0 0.5rem;
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 700;
}

.correction-form__grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
}

.correction-derived-values {
  margin-top: 1rem;
}

.correction-checkbox {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  margin-top: 1rem;
  line-height: 1.5;
}

.correction-checkbox input {
  width: 1.25rem;
  height: 1.25rem;
  margin: 0.125rem 0 0;
  accent-color: var(--colour-primary);
}

.correction-wickets-field textarea {
  min-height: 10rem;
}

.correction-form > .button {
  justify-self: start;
}

.correction-workspace > .submission-result,
.correction-workspace > div > .submission-result,
.correction-workspace > .state-message,
.correction-workspace > .fixture-statistics-overview {
  margin-top: 2rem;
}

.hero {
  position: relative;
  min-height: min(39rem, calc(100svh - 7.5rem));
  overflow: hidden;
  display: flex;
  align-items: center;
  border-bottom: 1px solid var(--colour-border);
  background: var(--colour-canvas);
}

.hero::before,
.hero::after {
  content: '';
  position: absolute;
  pointer-events: none;
}

.hero::before {
  inset: 2rem 0 2rem 50%;
  border-left: 1px solid var(--colour-border);
}

.hero::after {
  right: 3rem;
  bottom: 2rem;
  width: 7rem;
  border-bottom: 0.5rem solid var(--colour-brand);
}

.hero__content {
  position: relative;
  z-index: 2;
  width: min(100% - 3rem, 100rem);
  margin-inline: auto;
  padding-block: 4rem;
}

.eyebrow {
  margin: 0 0 1rem;
  color: var(--colour-label);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
}

h1,
h2,
h3,
p {
  overflow-wrap: anywhere;
}

h1,
h2,
h3 {
  font-family: var(--font-display);
  letter-spacing: 0;
}

h1 {
  margin: 0;
  font-size: 4.5rem;
  line-height: 1;
  text-wrap: balance;
  white-space: nowrap;
}

.hero__tagline {
  max-width: 30rem;
  margin: 1.5rem 0 0;
  color: var(--colour-brand);
  font-family: var(--font-display);
  font-size: 2rem;
  font-weight: 700;
  line-height: 1.15;
}

.hero__summary {
  max-width: 35rem;
  margin: 1.5rem 0 0;
  color: var(--colour-text-secondary);
  font-size: 1.125rem;
  line-height: 1.6;
}

.hero__brand-art {
  position: absolute;
  z-index: 1;
  right: max(1.5rem, calc((100vw - 100rem) / 2));
  bottom: -1rem;
  width: min(38vw, 31rem);
  pointer-events: none;
}

.hero__logo {
  width: 100%;
  height: auto;
}

.principles {
  padding-block: 5rem;
  background: var(--colour-surface);
}

.section-heading {
  display: grid;
  grid-template-columns: minmax(8rem, 0.7fr) minmax(0, 2fr);
  align-items: end;
  gap: 2rem;
  padding-bottom: 2rem;
  border-bottom: 1px solid var(--colour-border);
}

.section-heading .eyebrow {
  margin: 0;
}

h2 {
  max-width: 18ch;
  margin: 0;
  font-size: 2.5rem;
  line-height: 1.1;
}

.principles__grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 2.5rem;
}

.principles article {
  padding-top: 2rem;
}

.principle-number {
  margin: 0 0 2rem;
  color: var(--colour-brand-text);
  font-family: var(--font-display);
  font-size: 0.875rem;
  font-weight: 700;
}

h3 {
  margin: 0;
  font-size: 1.5rem;
  line-height: 1.2;
}

.principles article p:last-child {
  max-width: 28ch;
  margin: 0.75rem 0 0;
  color: var(--colour-text-secondary);
  line-height: 1.6;
}

.site-footer {
  border-top: 1px solid var(--colour-border);
  background: var(--colour-surface-raised);
}

.site-footer__inner {
  min-height: 8rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
}

.site-footer p {
  margin: 0;
  color: var(--colour-text-secondary);
  font-size: 0.875rem;
}

.browse-page {
  min-height: 38rem;
  padding-bottom: 5rem;
}

.page-heading {
  padding-block: 2rem 1.5rem;
}

.page-heading h1 {
  max-width: 20ch;
  margin: 0;
  font-size: 3.25rem;
  line-height: 1;
  white-space: normal;
}

.page-heading > p:last-child {
  max-width: 47rem;
  margin: 1rem 0 0;
  color: var(--colour-text-secondary);
  font-size: 1.0625rem;
  line-height: 1.6;
}

.browse-page__content {
  display: grid;
  gap: 2rem;
}

.filter-panel {
  padding: 1.5rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface-raised);
}

.filter-panel__heading,
.results-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.filter-panel h2,
.results-heading h2,
.related-records h2 {
  max-width: none;
  font-size: 1.5rem;
}

.text-link,
.back-link {
  color: var(--colour-link);
  font-weight: 650;
  text-underline-offset: 0.2em;
}

.filter-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1rem;
  margin-block: 1.25rem;
}

.field {
  display: grid;
  align-content: start;
  gap: 0.5rem;
  min-width: 0;
}

.field > span,
.field > label {
  color: var(--colour-text-secondary);
  font-size: 0.8125rem;
  font-weight: 650;
}

.field input,
.field select {
  width: 100%;
  min-width: 0;
  min-height: 2.75rem;
  padding: 0.625rem 0.75rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface);
  color: var(--colour-text);
}

.name-combobox {
  position: relative;
}

.name-combobox__control {
  position: relative;
  display: flex;
}

.name-combobox__control input {
  padding-right: 4.5rem;
}

.name-combobox__clear,
.name-combobox__toggle {
  position: absolute;
  top: 50%;
  min-height: 2rem;
  border: 0;
  background: transparent;
  color: var(--colour-link);
  cursor: pointer;
  transform: translateY(-50%);
}

.name-combobox__clear {
  right: 2rem;
  padding-inline: 0.375rem;
  font-size: 0.75rem;
  font-weight: 650;
}

.name-combobox__toggle {
  right: 0.25rem;
  width: 2rem;
  padding: 0;
  color: var(--colour-text);
}

.name-combobox__clear:focus-visible,
.name-combobox__toggle:focus-visible {
  outline-offset: 0;
}

.name-combobox__popover {
  position: absolute;
  z-index: 20;
  top: calc(100% + 0.25rem);
  right: 0;
  left: 0;
  overflow: hidden;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface);
  box-shadow: var(--shadow-overlay);
}

.name-combobox__options {
  max-height: 18rem;
  margin: 0;
  padding: 0.25rem;
  overflow-y: auto;
  list-style: none;
}

.name-combobox__option {
  display: grid;
  gap: 0.125rem;
  padding: 0.625rem 0.75rem;
  border-radius: 4px;
  cursor: pointer;
}

.name-combobox__option.is-active,
.name-combobox__option[aria-selected='true'] {
  background: var(--colour-primary-soft);
}

.name-combobox__option span {
  color: var(--colour-text);
  font-size: 0.9375rem;
  font-weight: 650;
}

.name-combobox__option small {
  color: var(--colour-text-secondary);
  font-size: 0.75rem;
  line-height: 1.4;
}

.name-combobox__option .name-combobox__selected-marker {
  color: var(--colour-text);
  font-weight: 650;
}

.name-combobox__state {
  margin: 0;
  padding: 0.875rem;
  color: var(--colour-text-secondary);
  font-size: 0.875rem;
  line-height: 1.5;
}

.name-combobox__state--error {
  border-left: 3px solid var(--colour-error);
  background: var(--colour-error-soft);
}

.name-combobox__state--error p {
  margin: 0;
}

.name-combobox__state .button {
  width: 100%;
  margin-top: 0.75rem;
}

.field-error {
  margin: 0;
  color: var(--colour-error);
  font-size: 0.8125rem;
  line-height: 1.4;
}

.active-filter-summary {
  margin-bottom: 1.25rem;
  padding: 1rem;
  border-left: 3px solid var(--colour-primary);
  background: var(--colour-surface);
}

.active-filter-summary h3 {
  margin: 0;
  font-size: 1rem;
}

.active-filter-summary ul {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1.25rem;
  margin: 0.625rem 0 0;
  padding: 0;
  list-style: none;
}

.active-filter-summary li {
  color: var(--colour-text-secondary);
  font-size: 0.875rem;
}

.active-filter-summary li span {
  color: var(--colour-text);
  font-weight: 650;
}

.visually-hidden {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

.button {
  display: inline-flex;
  min-height: 2.75rem;
  align-items: center;
  justify-content: center;
  padding: 0.625rem 1rem;
  border: 1px solid transparent;
  border-radius: 6px;
  cursor: pointer;
  font-weight: 700;
  text-decoration: none;
}

.button--primary {
  background: var(--colour-primary);
  color: var(--colour-surface);
}

:root[data-theme='night'] .button--primary {
  color: var(--colour-canvas);
}

.button--secondary {
  border-color: var(--colour-border);
  background: var(--colour-surface);
  color: var(--colour-text);
}

.button:hover {
  filter: brightness(0.94);
}

.results-region {
  min-width: 0;
}

.results-heading {
  padding-bottom: 1rem;
  border-bottom: 2px solid var(--colour-primary);
}

.results-heading p {
  margin: 0;
  color: var(--colour-text-muted);
  font-size: 0.875rem;
}

.record-list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.record-list__item {
  display: grid;
  grid-template-columns: minmax(8rem, 0.7fr) minmax(0, 1.8fr) minmax(12rem, 1fr);
  align-items: center;
  gap: 1.5rem;
  padding-block: 1.5rem;
  border-bottom: 1px solid var(--colour-border);
}

.record-list__meta,
.record-list__summary {
  margin: 0;
  color: var(--colour-text-secondary);
  font-size: 0.875rem;
  line-height: 1.5;
}

.record-list__item h3 {
  min-width: 0;
}

.record-list__item h3 a {
  color: var(--colour-text);
  text-decoration-color: var(--colour-primary);
  text-decoration-thickness: 2px;
  text-underline-offset: 0.2em;
}

.state-message {
  margin-top: 1.5rem;
  padding: 1.5rem;
  border-left: 3px solid var(--colour-data-accent);
  background: var(--colour-surface-raised);
}

.state-message--error {
  border-left-color: var(--colour-error);
  background: var(--colour-error-soft);
}

.state-message h1,
