:root[data-theme='night'] {
  --colour-canvas: #08121b;
  --colour-surface: #101e2b;
  --colour-surface-raised: #162736;
  --colour-text: #f6f8f2;
  --colour-text-secondary: #b8c3cc;
  --colour-text-muted: #8ea0af;
  --colour-border: #263847;
  --colour-primary: #c7ff4a;
  --colour-primary-soft: #263b21;
  --colour-brand: #ff6b35;
  --colour-data-accent: #20d5ff;
  --colour-link: #20d5ff;
  --colour-label: #c7ff4a;
  --colour-brand-text: #ff8a5e;
  --colour-error: #ff8a7a;
  --colour-focus: #c7ff4a;
  --colour-error: #ff5a67;
  --colour-error-soft: #361b24;
  --shadow-header: 0 8px 28px rgb(0 0 0 / 24%);
}

* {
  box-sizing: border-box;
}

html {
  min-width: 320px;
  background: var(--colour-canvas);
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  overflow-x: hidden;
  background: var(--colour-canvas);
  color: var(--colour-text);
}

button,
input,
select {
  font: inherit;
}

a {
  color: var(--colour-link);
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible {
  outline: 3px solid var(--colour-focus);
  outline-offset: 4px;
}

.public-shell {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.skip-link {
  position: fixed;
  left: 1rem;
  top: -5rem;
  z-index: 100;
  padding: 0.75rem 1rem;
  border: 2px solid var(--colour-focus);
  border-radius: 6px;
  background: var(--colour-surface);
  color: var(--colour-text);
  font-weight: 600;
  text-decoration: none;
}

.skip-link:focus {
  top: 1rem;
}

.site-header {
  position: relative;
  z-index: 10;
  border-bottom: 1px solid var(--colour-border);
  background: var(--colour-surface);
  box-shadow: var(--shadow-header);
}

.site-header__inner,
.site-footer__inner,
.content-boundary {
  width: min(100% - 3rem, 100rem);
  margin-inline: auto;
}

.site-header__inner {
  min-height: 5.5rem;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 1.5rem;
}

.site-header__controls,
.auth-navigation,
.auth-navigation-wrap {
  display: flex;
  align-items: center;
}

.site-header__controls {
  justify-content: flex-end;
  gap: 1.5rem;
}

.auth-navigation-wrap {
  position: relative;
  align-self: stretch;
}

.auth-navigation {
  gap: 0.5rem;
}

.auth-navigation a,
.auth-navigation button {
  min-height: 2.75rem;
  display: inline-flex;
  align-items: center;
  padding: 0.625rem 0.75rem;
  border: 1px solid transparent;
  border-radius: 6px;
  background: transparent;
  color: var(--colour-text);
  font-weight: 600;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
}

.auth-navigation a:hover,
.auth-navigation button:hover:not(:disabled),
.auth-navigation a[aria-current='page'] {
  border-color: var(--colour-border);
  background: var(--colour-surface-raised);
}

.auth-navigation a[aria-current='page'] {
  box-shadow: inset 0 -3px var(--colour-primary);
}

.auth-navigation button:disabled {
  cursor: wait;
  opacity: 0.7;
}

.auth-navigation__status {
  margin: 0;
  color: var(--colour-text-secondary);
  font-size: 0.875rem;
}

.auth-navigation__error {
  position: absolute;
  top: calc(100% - 0.25rem);
  right: 0;
  width: max-content;
  max-width: min(22rem, calc(100vw - 2rem));
  margin: 0;
  padding: 0.75rem 1rem;
  border: 1px solid var(--colour-error);
  border-radius: 6px;
  background: var(--colour-surface);
  color: var(--colour-error);
  box-shadow: var(--shadow-header);
  font-size: 0.875rem;
}

.brand-link {
  display: inline-flex;
  align-items: center;
  min-width: 0;
  border-radius: 6px;
}

.brand-wordmark {
  display: block;
  width: 11rem;
  max-width: 100%;
}

.brand-wordmark__image {
  display: block;
  width: 100%;
  height: auto;
}

.site-navigation {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.25rem;
}

.site-navigation a {
  position: relative;
  padding: 0.75rem 0.625rem;
  border-radius: 6px;
  color: var(--colour-text-secondary);
  font-size: 0.8125rem;
  font-weight: 650;
  text-align: center;
  text-decoration: none;
}

.site-navigation a:hover {
  background: var(--colour-surface-raised);
  color: var(--colour-text);
}

.site-navigation a.active {
  background: var(--colour-primary-soft);
  color: var(--colour-text);
}

.site-navigation a.active::after {
  content: '';
  position: absolute;
  right: 0.625rem;
  bottom: 0.375rem;
  left: 0.625rem;
  border-bottom: 2px solid var(--colour-primary);
}

.brand-asset--night {
  display: none;
}

:root[data-theme='night'] .brand-asset--day {
  display: none;
}

:root[data-theme='night'] .brand-asset--night {
  display: block;
}

.theme-control {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--colour-text-secondary);
}

.theme-control__label {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
}

.theme-toggle {
  position: relative;
  display: flex;
  margin-top: 1rem;
  line-height: 1.5;
}

.correction-checkbox input {
  width: 1.25rem;
  height: 1.25rem;
  margin: 0.125rem 0 0;
  accent-color: var(--colour-primary);
}

.correction-wickets-field textarea {
  min-height: 10rem;
}

.correction-form > .button {
  justify-self: start;
}

.correction-workspace > .submission-result,
.correction-workspace > div > .submission-result,
.correction-workspace > .state-message,
.correction-workspace > .fixture-statistics-overview {
  margin-top: 2rem;
}

.hero {
  position: relative;
  min-height: min(39rem, calc(100svh - 7.5rem));
  overflow: hidden;
  display: flex;
  align-items: center;
  border-bottom: 1px solid var(--colour-border);
  background: var(--colour-canvas);
}

.hero::before,
.hero::after {
  content: '';
  position: absolute;
  pointer-events: none;
}

.hero::before {
  inset: 2rem 0 2rem 50%;
  border-left: 1px solid var(--colour-border);
}

.hero::after {
  right: 3rem;
  bottom: 2rem;
  width: 7rem;
  border-bottom: 0.5rem solid var(--colour-brand);
}

.hero__content {
  position: relative;
  z-index: 2;
  width: min(100% - 3rem, 100rem);
  margin-inline: auto;
  padding-block: 4rem;
}

.eyebrow {
  margin: 0 0 1rem;
  color: var(--colour-label);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
}

h1,
h2,
h3,
p {
  overflow-wrap: anywhere;
}

h1,
h2,
h3 {
  font-family: var(--font-display);
  letter-spacing: 0;
}

h1 {
  margin: 0;
  font-size: 4.5rem;
  line-height: 1;
  text-wrap: balance;
  white-space: nowrap;
}

.hero__tagline {
  max-width: 30rem;
  margin: 1.5rem 0 0;
  color: var(--colour-brand);
  font-family: var(--font-display);
  font-size: 2rem;
  font-weight: 700;
  line-height: 1.15;
}

.hero__summary {
  max-width: 35rem;
  margin: 1.5rem 0 0;
  color: var(--colour-text-secondary);
  font-size: 1.125rem;
  line-height: 1.6;
}

.hero__brand-art {
  position: absolute;
  z-index: 1;
  right: max(1.5rem, calc((100vw - 100rem) / 2));
  bottom: -1rem;
  width: min(38vw, 31rem);
  pointer-events: none;
}

.hero__logo {
  width: 100%;
  height: auto;
}

.principles {
  padding-block: 5rem;
  background: var(--colour-surface);
}

.section-heading {
  display: grid;
  grid-template-columns: minmax(8rem, 0.7fr) minmax(0, 2fr);
  align-items: end;
  gap: 2rem;
  padding-bottom: 2rem;
  border-bottom: 1px solid var(--colour-border);
}

.section-heading .eyebrow {
  margin: 0;
}

h2 {
  max-width: 18ch;
  margin: 0;
  font-size: 2.5rem;
  line-height: 1.1;
}

.principles__grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 2.5rem;
}

.principles article {
  padding-top: 2rem;
}

.principle-number {
  margin: 0 0 2rem;
  color: var(--colour-brand-text);
  font-family: var(--font-display);
  font-size: 0.875rem;
  font-weight: 700;
}

h3 {
  margin: 0;
  font-size: 1.5rem;
  line-height: 1.2;
}

.principles article p:last-child {
  max-width: 28ch;
  margin: 0.75rem 0 0;
  color: var(--colour-text-secondary);
  line-height: 1.6;
}

.site-footer {
  border-top: 1px solid var(--colour-border);
  background: var(--colour-surface-raised);
}

.site-footer__inner {
  min-height: 8rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
}

.site-footer p {
  margin: 0;
  color: var(--colour-text-secondary);
  font-size: 0.875rem;
}
