import { useEffect, useRef } from 'react';
import {
  BoxGeometry,
  BufferGeometry,
  CatmullRomCurve3,
  Color,
  CylinderGeometry,
  LineBasicMaterial,
  LineSegments,
  Mesh,
  MeshBasicMaterial,
  PerspectiveCamera,
  Scene,
  SphereGeometry,
  TorusGeometry,
  TubeGeometry,
  Vector3,
  WebGLRenderer,
  type Material,
} from 'three';

interface HeroSceneProps {
  onReady: () => void;
}

const DELIVERY_DURATION = 1_850;
const REST_DURATION = 1_600;

function semanticColour(styles: CSSStyleDeclaration, name: string, fallback: string): Color {
  return new Color(styles.getPropertyValue(name).trim() || fallback);
}

export function HeroScene({ onReady }: HeroSceneProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

