      rememberGeometry(
        new BufferGeometry().setFromPoints([
          new Vector3(0.65, 0.16, -2.15),
          new Vector3(2.6, 0.16, -2.15),
          new Vector3(2.6, 0.16, -2.15),
          new Vector3(2.6, 0.16, 0.65),
        ]),
      ),
      connectionMaterial,
    );
