    await session.send('Emulation.setDeviceMetricsOverride', {
      width: Math.floor(viewport.width / 2),
      height: viewport.height,
      deviceScaleFactor: 2,
      mobile: false,
    });
  }

  await expectReadableAccessibleView(page, internalValues);
});

