const r = await tools.shell_command({
  command: "@'
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  const started = Date.now();
  const stamp = () => `${Date.now() - started}ms`;
  page.on('console', msg => console.log(`CONSOLE ${stamp()} ${msg.type()}: ${msg.text()}`));
  page.on('pageerror', err => console.log(`PAGEERROR ${stamp()}: ${err.stack || err.message}`));
  page.on('crash', () => console.log(`PAGECRASH ${stamp()}`));
  await page.addInitScript(() => {
    window.__webglEvents = [];
    document.addEventListener('webglcontextlost', event => {
      window.__webglEvents.push({ type: 'lost', time: Math.round(performance.now()), target: event.target?.className || '' });
    }, true);
    document.addEventListener('webglcontextrestored', event => {
      window.__webglEvents.push({ type: 'restored', time: Math.round(performance.now()), target: event.target?.className || '' });
    }, true);
  });
  await page.goto('http://127.0.0.1:5174/', { waitUntil: 'networkidle' });
  for (let i = 0; i < 20; i += 1) {
    await page.waitForTimeout(1000);
    const state = await page.evaluate(() => ({
      canvases: document.querySelectorAll('.hero-scene').length,
      enhancement: document.querySelector('[data-hero-enhancement]')?.getAttribute('data-hero-enhancement'),
      animation: document.querySelector('.hero-scene')?.getAttribute('data-animation-state'),
      webglEvents: window.__webglEvents,
    }));
    console.log(`STATE ${stamp()} ${JSON.stringify(state)}`);
  }
  await browser.close();
})().catch(error => { console.error(error); process.exit(1); });
