  console.log(`FINAL_STATE ${JSON.stringify(state)}`);
  console.log(`WEBGL_ERRORS ${JSON.stringify(messages.filter(line => /webgl|three|context lost|pageerror/i.test(line)))}`);
  await browser.close();
})().catch(error => { console.error(error); process.exit(1); });
