const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  const pageErrors = [];
  page.on('pageerror', error => pageErrors.push(error.stack || error.message));
  page.on('console', msg => { if (msg.type() === 'error') console.log(`CONSOLE_ERROR ${msg.text()}`); });
  await page.goto('http://127.0.0.1:5174/', { waitUntil: 'networkidle' });
  await page.waitForSelector('[data-hero-enhancement="three"]');
  const supported = await page.evaluate(() => {
    const canvas = document.querySelector('.hero-scene');
    const context = canvas?.getContext('webgl2') ?? canvas?.getContext('webgl');
    const extension = context?.getExtension('WEBGL_lose_context');
    if (!extension) return false;
    window.__restoreHeroContext = () => extension.restoreContext();
    extension.loseContext();
    return true;
  });
  console.log(`LOSS_EXTENSION=${supported}`);
  if (supported) {
    await page.waitForSelector('[data-hero-enhancement="fallback"]');
    console.log(`LOST_STATE=${JSON.stringify(await page.evaluate(() => ({ enhancement: document.querySelector('[data-hero-enhancement]')?.getAttribute('data-hero-enhancement'), context: document.querySelector('.hero-scene')?.getAttribute('data-context-state'), animation: document.querySelector('.hero-scene')?.getAttribute('data-animation-state'), opacity: getComputedStyle(document.querySelector('.hero-scene')).opacity, canvases: document.querySelectorAll('.hero-scene').length })))}`);
    await page.evaluate(() => window.__restoreHeroContext());
    await page.waitForSelector('[data-hero-enhancement="three"]');
    console.log(`RESTORED_STATE=${JSON.stringify(await page.evaluate(() => ({ enhancement: document.querySelector('[data-hero-enhancement]')?.getAttribute('data-hero-enhancement'), context: document.querySelector('.hero-scene')?.getAttribute('data-context-state'), animation: document.querySelector('.hero-scene')?.getAttribute('data-animation-state'), canvases: document.querySelectorAll('.hero-scene').length })))}`);
  }
  console.log(`PAGE_ERRORS=${JSON.stringify(pageErrors)}`);
  await browser.close();
})().catch(error => { console.error(error); process.exit(1); });
