(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const backgroundPage = await browser.newPage();
  const consoleErrors = [];
  const pageErrors = [];
  page.on('console', message => { if (message.type() === 'error') consoleErrors.push(message.text()); });
  page.on('pageerror', error => pageErrors.push(error.stack || error.message));
  await page.addInitScript(() => {
    const diagnostics = window;
    diagnostics.__heroSoak = { contextLosses: 0, contextRestores: 0, pendingRafs: 0, maxPendingRafs: 0 };
    const originalRequest = window.requestAnimationFrame.bind(window);
    const originalCancel = window.cancelAnimationFrame.bind(window);
    const pending = new Set();
    window.requestAnimationFrame = callback => {
      let requestId = 0;
      requestId = originalRequest(time => {
        pending.delete(requestId);
        diagnostics.__heroSoak.pendingRafs = pending.size;
        callback(time);
      });
      pending.add(requestId);
      diagnostics.__heroSoak.pendingRafs = pending.size;
      diagnostics.__heroSoak.maxPendingRafs = Math.max(diagnostics.__heroSoak.maxPendingRafs, pending.size);
      return requestId;
    };
    window.cancelAnimationFrame = requestId => {
      pending.delete(requestId);
      diagnostics.__heroSoak.pendingRafs = pending.size;
      originalCancel(requestId);
    };
    document.addEventListener('webglcontextlost', event => {
      if (event.target instanceof HTMLCanvasElement && event.target.matches('.hero-scene')) diagnostics.__heroSoak.contextLosses += 1;
    }, true);
    document.addEventListener('webglcontextrestored', event => {
      if (event.target instanceof HTMLCanvasElement && event.target.matches('.hero-scene')) diagnostics.__heroSoak.contextRestores += 1;
    }, true);
  });
  await backgroundPage.goto('about:blank');
  await page.goto('http://127.0.0.1:5174/', { waitUntil: 'networkidle' });
  await page.waitForSelector('[data-hero-enhancement="three"]');
  const started = Date.now();
  let cycles = 0;
  let maxCanvases = 0;
  const states = [];
  while (Date.now() - started < 120000) {
    const cycleStarted = Date.now();
    cycles += 1;
    const toggle = page.getByLabel(/Switch to (Day|Night) Match theme/);
    await toggle.click();
    await page.locator('.home-cta').scrollIntoViewIfNeeded();
    await page.waitForTimeout(350);
    const offscreenState = await page.locator('.hero-scene').getAttribute('data-animation-state');
    await page.evaluate(() => window.scrollTo({ top: 0, behavior: 'instant' }));
    await page.waitForTimeout(350);
    await backgroundPage.bringToFront();
    await page.waitForTimeout(350);
    await page.bringToFront();
    await page.waitForTimeout(350);
    await page.setViewportSize(cycles % 2 === 0 ? { width: 1440, height: 900 } : { width: 390, height: 844 });
    if (cycles % 3 === 0) {
      await page.getByRole('link', { name: 'Browse fixtures' }).first().click();
      await page.waitForSelector('h1');
      await page.goBack();
      await page.waitForSelector('[data-hero-enhancement="three"]');
    }
    const sample = await page.evaluate(() => ({
      canvases: document.querySelectorAll('.hero-scene').length,
      enhancement: document.querySelector('[data-hero-enhancement]')?.getAttribute('data-hero-enhancement'),
      animation: document.querySelector('.hero-scene')?.getAttribute('data-animation-state'),
      context: document.querySelector('.hero-scene')?.getAttribute('data-context-state'),
      theme: document.documentElement.dataset.theme,
      diagnostics: window.__heroSoak,
    }));
    maxCanvases = Math.max(maxCanvases, sample.canvases);
    states.push({ cycle: cycles, offscreenState, ...sample });
    const remaining = 10000 - (Date.now() - cycleStarted);
    if (remaining > 0) await page.waitForTimeout(remaining);
  }
  const finalState = states.at(-1);
  console.log(JSON.stringify({ durationMs: Date.now() - started, cycles, maxCanvases, finalState, consoleErrors, pageErrors, allOffscreenPaused: states.every(state => state.offscreenState === 'paused'), allContextsReady: states.every(state => state.context === 'ready'), allEnhancementsActive: states.every(state => state.enhancement === 'three') }, null, 2));
  await browser.close();
})().catch(error => { console.error(error); process.exit(1); });
